package com.campusevents.ui;
import com.campusevents.model.*;import com.campusevents.service.*;import com.campusevents.dao.*;import com.campusevents.util.CSVExporter;import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.time.*;import java.util.*;
public class AdminFrame extends JFrame {private final User admin;private final EventService es=new EventService();private final RegistrationService rs=new RegistrationService();private final DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Title","Category","Date","Venue","Capacity","Confirmed","Waitlist","Status"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable t=new JTable(m);public AdminFrame(User u){super("Administrator dashboard");admin=u;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1120,650);setLocationRelativeTo(null);JPanel p=new JPanel(new BorderLayout(8,8));p.setBorder(BorderFactory.createEmptyBorder(15,15,15,15));JLabel h=new JLabel("Campus events administration");h.setFont(new Font("SansSerif",Font.BOLD,24));p.add(h,BorderLayout.NORTH);p.add(new JScrollPane(t));JPanel a=new JPanel(new FlowLayout(FlowLayout.LEFT));String[] labels={"Create event","Edit selected","Cancel event","Participants","Students","Export CSV","Refresh","Log out"};JButton[] bs=new JButton[labels.length];for(int i=0;i<labels.length;i++){bs[i]=new JButton(labels[i]);a.add(bs[i]);}p.add(a,BorderLayout.SOUTH);setContentPane(p);bs[0].addActionListener(e->edit(null));bs[1].addActionListener(e->{com.campusevents.model.Event x=selected();if(x!=null)edit(x);});bs[2].addActionListener(e->{com.campusevents.model.Event x=selected();if(x!=null)try{es.cancel(admin,x.id());load();}catch(Exception z){error(z);}});bs[3].addActionListener(e->participants());bs[4].addActionListener(e->students());bs[5].addActionListener(e->export());bs[6].addActionListener(e->load());bs[7].addActionListener(e->{dispose();new LoginFrame().setVisible(true);});load();}private com.campusevents.model.Event selected(){int r=t.getSelectedRow();if(r<0){warn("Select an event.");return null;}try{return es.get((Integer)m.getValueAt(t.convertRowIndexToModel(r),0));}catch(Exception e){error(e);return null;}}private void load(){try{m.setRowCount(0);for(com.campusevents.model.Event e:es.search("","All"))m.addRow(new Object[]{e.id(),e.title(),e.category(),e.date(),e.venue(),e.capacity(),e.confirmed(),e.waitlisted(),e.status()});}catch(Exception e){error(e);}}private void edit(com.campusevents.model.Event old){JTextField[] f=new JTextField[10];String[] labels={"Title","Description","Category","Organizer","Date YYYY-MM-DD","Start HH:MM","End HH:MM","Venue","Deadline YYYY-MM-DD","Capacity"};String[] vals=old==null?new String[]{"","","Technical","Campus Events Committee",LocalDate.now().plusDays(7).toString(),"10:00","12:00","Main Auditorium",LocalDate.now().plusDays(5).toString(),"100"}:new String[]{old.title(),old.description(),old.category(),old.organizer(),old.date().toString(),old.start().toString(),old.end().toString(),old.venue(),old.deadline().toString(),String.valueOf(old.capacity())};JPanel p=new JPanel(new GridLayout(0,2,5,5));for(int i=0;i<10;i++){f[i]=new JTextField(vals[i],20);p.add(new JLabel(labels[i]));p.add(f[i]);}JComboBox<String> status=new JComboBox<>(new String[]{"UPCOMING","ONGOING","COMPLETED","CANCELLED"});if(old!=null)status.setSelectedItem(old.status());p.add(new JLabel("Status"));p.add(status);if(JOptionPane.showConfirmDialog(this,p,old==null?"Create event":"Edit event",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)try{es.save(admin,old==null?0:old.id(),f[0].getText(),f[1].getText(),f[2].getText(),f[3].getText(),LocalDate.parse(f[4].getText()),LocalTime.parse(f[5].getText()),LocalTime.parse(f[6].getText()),f[7].getText(),LocalDate.parse(f[8].getText()),Integer.parseInt(f[9].getText()),(String)status.getSelectedItem());load();}catch(Exception e){error(e);}}private void participants(){com.campusevents.model.Event e=selected();if(e==null)return;try{StringBuilder b=new StringBuilder("Student ID | Name | Email | Registration | Status\n");for(String[] r:rs.participants(admin,e.id()))b.append(String.join(" | ",r)).append("\n");JTextArea a=new JTextArea(b.toString(),20,75);a.setEditable(false);JOptionPane.showMessageDialog(this,new JScrollPane(a),"Participants",JOptionPane.INFORMATION_MESSAGE);}catch(Exception x){error(x);}}private void students(){try{StringBuilder b=new StringBuilder("Name | Email | College ID | Department | Year | Phone\n");for(String[] r:new UserDAO().students())b.append(String.join(" | ",r)).append("\n");JTextArea a=new JTextArea(b.toString(),20,75);a.setEditable(false);JOptionPane.showMessageDialog(this,new JScrollPane(a),"Students",JOptionPane.INFORMATION_MESSAGE);}catch(Exception e){error(e);}}private void export(){com.campusevents.model.Event e=selected();if(e==null)return;JFileChooser fc=new JFileChooser();fc.setSelectedFile(new java.io.File("event-"+e.id()+"-registrations.csv"));if(fc.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)try{CSVExporter.write(fc.getSelectedFile().toPath(),new String[]{"College ID","Name","Email","Registration ID","Status"},rs.participants(admin,e.id()));JOptionPane.showMessageDialog(this,"CSV exported.");}catch(Exception x){error(x);}}private void warn(String s){JOptionPane.showMessageDialog(this,s);}private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}}
